//! Integration test validating the bidirectional concolic fuzzing feedback loop.
//!
//! Validates:
//! - Setting up `FuzzSession` with `HavocMutator` and `FuzzCorpus`.
//! - Ingesting `ConstraintHint` items generated by concolic / SMT solver branch evaluations.
//! - Verifying that solver-derived seeds unlock new CFG edges, triggering the +100x
//!   edge-discovery scheduling boost in `FuzzCorpus`.
//! - Verifying that newly discovered branches feed back into the concolic solver query queue.
//! - Validating complete bidirectional feedback cycles between solver and fuzzer.

use std::time::Duration;

use angryier_fuzz::{
    ConstraintHint, CoverageDelta, FuzzCorpus, FuzzIntegrationStage, FuzzSeed, FuzzSession, InMemoryFuzzBridge, Mutator,
};
use angryier_solver::{
    BatchCoordinatorConfig, BranchId, CanonicalConstraint, MockSolverBackend, SolverOutcomeKind, SolverQuery,
    SpeculativeBatchCoordinator,
};
use angryier_types::{
    Address, ConstraintCanonicalizationVersion, ConstraintId, DependencyKey, ExprId, SolverQueryId, StateId,
    TargetProfileId,
};

/// Mutator driving multi-step havoc mutations within the concolic feedback loop.
#[derive(Debug)]
pub struct HavocMutator {
    /// Underlying mutator engine containing mutation primitives and PRNG.
    pub inner: Mutator,
    /// Number of sequential random mutation operations applied per havoc step.
    pub havoc_steps: usize,
}

impl HavocMutator {
    /// Creates a new `HavocMutator` with a configured number of havoc steps.
    pub fn new(havoc_steps: usize) -> Self {
        Self {
            inner: Mutator::new(),
            havoc_steps: havoc_steps.max(1),
        }
    }

    /// Creates a `HavocMutator` with predefined dictionary tokens.
    pub fn with_dictionary(havoc_steps: usize, dictionary: Vec<Vec<u8>>) -> Self {
        let mut inner = Mutator::new();
        inner.set_dictionary(dictionary);
        Self {
            inner,
            havoc_steps: havoc_steps.max(1),
        }
    }

    /// Performs havoc mutation on the input buffer.
    pub fn mutate(&mut self, input: &[u8], secondary: Option<&[u8]>) -> Vec<u8> {
        self.inner.havoc_mutate(input, secondary, self.havoc_steps)
    }
}

/// Helper to generate a deterministic 32-byte DependencyKey.
fn make_dep_key(val: u8) -> DependencyKey {
    let mut arr = [0u8; 32];
    arr[0] = val;
    arr[31] = val.wrapping_mul(7);
    DependencyKey(arr)
}

/// Constructs a canonical `SolverQuery` representing an inverted branch predicate.
fn make_branch_query(
    query_id: u64,
    branch_key_byte: u8,
    prior_constraint_bytes: &[u8],
) -> Result<SolverQuery, Box<dyn std::error::Error>> {
    let constraints: Vec<CanonicalConstraint> = prior_constraint_bytes
        .iter()
        .enumerate()
        .map(|(idx, &b)| CanonicalConstraint {
            id: ConstraintId(idx as u64 + 1),
            key: make_dep_key(b),
            expr: ExprId((idx + 1) as u32),
        })
        .collect();

    let query = SolverQuery::canonical(
        SolverQueryId(query_id),
        &constraints,
        ExprId(query_id as u32),
        make_dep_key(branch_key_byte),
        TargetProfileId(0),
        ConstraintCanonicalizationVersion(1),
        Duration::from_secs(5),
    )?;
    Ok(query)
}

#[test]
fn test_havoc_mutator_initialization_and_mutations() {
    let mut havoc = HavocMutator::new(8);
    let original = b"concolic_fuzz_seed_payload_1234";
    let mutated = havoc.mutate(original, None);

    assert!(!mutated.is_empty());
    // Havoc mutation should perturb the input while keeping bounds intact
    assert!(mutated.len() <= Mutator::new().max_input_size);
}

#[test]
fn test_fuzz_session_setup_with_havoc_mutator_and_fuzz_corpus() {
    let bridge = InMemoryFuzzBridge::new(FuzzIntegrationStage::Bidirectional);
    let corpus = FuzzCorpus::new();
    let havoc = HavocMutator::new(6);

    let mut session = FuzzSession::with_corpus_and_mutator(bridge, corpus, havoc.inner);
    assert_eq!(session.corpus().len(), 0);
    assert!(session.corpus().is_empty());

    let initial_seed = FuzzSeed {
        bytes: b"bootstrap_seed".to_vec(),
        origin_state: Some(StateId(0)),
        validity: make_dep_key(0x01),
    };

    let id = session.add_seed(initial_seed).expect("seed submission");
    assert_eq!(session.corpus().len(), 1);
    assert_eq!(session.bridge().seed_count(), 1);

    let entry = session.corpus().get(id).expect("corpus entry");
    assert_eq!(entry.seed.bytes, b"bootstrap_seed");
    assert_eq!(entry.energy, 120); // base energy for inputs < 32 bytes
}

#[test]
fn test_ingest_constraint_hints_from_solver_branch_evaluations() {
    let bridge = InMemoryFuzzBridge::new(FuzzIntegrationStage::Bidirectional);
    let corpus = FuzzCorpus::new();
    let havoc = HavocMutator::new(4);
    let mut session = FuzzSession::with_corpus_and_mutator(bridge, corpus, havoc.inner);

    // Initial corpus seed
    let init_seed = FuzzSeed {
        bytes: b"base".to_vec(),
        origin_state: Some(StateId(1)),
        validity: make_dep_key(0x10),
    };
    session.add_seed(init_seed).expect("add initial seed");

    // Simulate solver branch evaluation at address 0x401050 targeting 0x401080
    let branch_target: Address = 0x0040_1080;
    let hint = ConstraintHint {
        canonical_key: make_dep_key(0x2A),
        target: Some(branch_target),
    };

    // Ingest the solver-generated ConstraintHint
    let hint_id = session.ingest_hint(hint).expect("ingest constraint hint");

    assert_eq!(session.corpus().len(), 2);
    assert_eq!(session.bridge().hint_count(), 1);

    let hint_entry = session.corpus().get(hint_id).expect("hint entry in corpus");
    // Verify that solver hints receive boosted initial energy (saturating_mul(2))
    assert_eq!(
        hint_entry.energy, 200,
        "solver-derived hint should receive doubled energy"
    );

    // Verify seed bytes contain the canonical key and target address bytes
    assert!(hint_entry.seed.bytes.len() >= 32);
    assert_eq!(&hint_entry.seed.bytes[0..32], &make_dep_key(0x2A).0);
    let target_bytes = &hint_entry.seed.bytes[32..40];
    assert_eq!(target_bytes, &branch_target.to_le_bytes());
}

#[test]
fn test_solver_seeds_unlock_new_cfg_edges_and_trigger_100x_scheduling_boost() {
    let bridge = InMemoryFuzzBridge::new(FuzzIntegrationStage::Bidirectional);
    let corpus = FuzzCorpus::new();
    let havoc = HavocMutator::new(4);
    let mut session = FuzzSession::with_corpus_and_mutator(bridge, corpus, havoc.inner);

    // Base seed
    let base_seed = FuzzSeed {
        bytes: b"base_path".to_vec(),
        origin_state: Some(StateId(1)),
        validity: make_dep_key(0x01),
    };
    let base_id = session.add_seed(base_seed).expect("add seed");
    let base_weight = session.corpus().get(base_id).unwrap().scheduling_weight();

    // Solver inverts branch constraint and emits ConstraintHint
    let branch_addr: Address = 0x0040_1050;
    let new_target_addr: Address = 0x0040_1080;
    let hint = ConstraintHint {
        canonical_key: make_dep_key(0x77),
        target: Some(new_target_addr),
    };
    let hint_id = session.ingest_hint(hint).expect("ingest hint");

    let solver_seed = session.corpus().get(hint_id).unwrap().seed.clone();
    let weight_before_edge = session.corpus().get(hint_id).unwrap().scheduling_weight();

    // Fuzzer mutates/executes solver-derived seed and discovers new CFG edge
    let new_edge = (branch_addr, new_target_addr);
    let delta = CoverageDelta {
        blocks: vec![new_target_addr],
        edges: vec![new_edge],
    };

    let promo_id = session
        .record_coverage_result(hint_id, solver_seed, delta)
        .expect("record coverage result")
        .expect("must be promoted to corpus due to new edge");

    let promoted_entry = session.corpus().get(promo_id).expect("promoted entry");
    assert!(promoted_entry.discovered_edges.contains(&new_edge));
    assert!(promoted_entry.discovered_blocks.contains(&new_target_addr));
    assert!(promoted_entry.has_new_coverage);

    // Verify the +100x edge-discovery scheduling boost:
    // In CorpusEntry::scheduling_weight:
    //   energy = base (100) + 1*50 (edge) + 1*25 (block) = 175
    //   edge_count > 0: weight += edge_count * 100 (the +100x edge boost)
    //   block_count > 0: weight += block_count * 20
    //   has_new_coverage: weight *= 2
    // Expected total weight = (175 + 100 + 20) * 2 = 590
    let boosted_weight = promoted_entry.scheduling_weight();
    assert_eq!(
        boosted_weight, 590,
        "new CFG edge discovery must receive +100x edge boost and coverage multiplier"
    );

    // Compare with base seed weight without edges
    assert!(
        boosted_weight > base_weight * 4,
        "edge-discovering solver seed weight ({boosted_weight}) must substantially exceed base seed weight ({base_weight})"
    );
    assert!(
        boosted_weight > weight_before_edge,
        "weight after CFG edge discovery must exceed weight before edge discovery"
    );
}

#[test]
fn test_newly_discovered_branches_feed_back_into_concolic_solver_queue() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Initialize fuzzer session
    let bridge = InMemoryFuzzBridge::new(FuzzIntegrationStage::Bidirectional);
    let corpus = FuzzCorpus::new();
    let havoc = HavocMutator::new(5);
    let mut session = FuzzSession::with_corpus_and_mutator(bridge, corpus, havoc.inner);

    // 2. Initialize concolic SMT solver batch coordinator (the query queue)
    let mock_solver = MockSolverBackend::new("z3_concolic_mock", SolverOutcomeKind::Sat);
    let coordinator_config = BatchCoordinatorConfig {
        max_batch_size: 4,
        timeout: Duration::from_millis(500),
        enable_background_worker: false, // manual/deterministic batch trigger
    };
    let coordinator = SpeculativeBatchCoordinator::new(Box::new(mock_solver), coordinator_config);

    assert_eq!(coordinator.queue_len(), 0, "solver queue must be empty initially");

    // 3. Fuzzer explores seed and discovers new branch condition at 0x0040_1080
    let branch_site: Address = 0x0040_1080;
    let branch_target_taken: Address = 0x0040_10B0;
    let branch_edge = (branch_site, branch_target_taken);

    let seed = FuzzSeed {
        bytes: b"path_exploring_branch".to_vec(),
        origin_state: Some(StateId(42)),
        validity: make_dep_key(0x33),
    };
    let seed_id = session.add_seed(seed.clone())?;

    let delta = CoverageDelta {
        blocks: vec![branch_site, branch_target_taken],
        edges: vec![branch_edge],
    };
    let _ = session.record_coverage_result(seed_id, seed, delta)?;

    // 4. FEEDBACK LOOP: The newly discovered branch is formulated as a concolic solver query
    // and submitted into the SMT solver query queue.
    let branch_query = make_branch_query(1001, 0x55, &[0x11, 0x22])?;
    let branch_key = make_dep_key(0x55);

    let waiter = coordinator.submit_query(StateId(42), BranchId(1), branch_key, branch_query);

    // Verify that the newly discovered branch entered the concolic solver query queue!
    assert_eq!(
        coordinator.queue_len(),
        1,
        "newly discovered branch must be queued in the concolic solver query queue"
    );

    // 5. Submit additional concurrent branch query from another edge
    let second_query = make_branch_query(1002, 0x66, &[0x11, 0x33])?;
    let second_waiter = coordinator.submit_query(StateId(43), BranchId(0), make_dep_key(0x66), second_query);
    assert_eq!(coordinator.queue_len(), 2);

    // 6. Trigger batch solver evaluation: drains queue and solves branch queries
    coordinator.trigger_batch();
    assert_eq!(
        coordinator.queue_len(),
        0,
        "queue must be drained after batch evaluation"
    );

    let res1 = waiter.wait()?;
    let res2 = second_waiter.wait()?;
    assert_eq!(res1.outcome, SolverOutcomeKind::Sat);
    assert_eq!(res2.outcome, SolverOutcomeKind::Sat);

    let metrics = coordinator.metrics();
    assert_eq!(metrics.total_batched, 2);

    // 7. Complete the feedback loop: solver solutions generate new ConstraintHint items
    // which feed right back into the fuzzer session!
    let next_hint = ConstraintHint {
        canonical_key: branch_key,
        target: Some(0x0040_10C0), // alternative branch target solved by concolic engine
    };
    let next_hint_id = session.ingest_hint(next_hint)?;

    let next_entry = session.corpus().get(next_hint_id).expect("next hint in corpus");
    assert_eq!(next_entry.energy, 200);

    Ok(())
}

#[test]
fn test_multi_round_bidirectional_concolic_fuzzing_loop() -> Result<(), Box<dyn std::error::Error>> {
    let bridge = InMemoryFuzzBridge::new(FuzzIntegrationStage::Bidirectional);
    let corpus = FuzzCorpus::new();
    let mut havoc = HavocMutator::new(8);
    let mut session = FuzzSession::with_corpus_and_mutator(bridge, corpus, Mutator::new());

    let mock_solver = MockSolverBackend::new("z3_concolic_portfolio", SolverOutcomeKind::Sat);
    let config = BatchCoordinatorConfig {
        max_batch_size: 2, // triggers automatically every 2 queries
        timeout: Duration::from_millis(200),
        enable_background_worker: false,
    };
    let coordinator = SpeculativeBatchCoordinator::new(Box::new(mock_solver), config);

    // Initial seed bootstrap
    let init_seed = FuzzSeed {
        bytes: vec![0x00, 0x01, 0x02, 0x03],
        origin_state: Some(StateId(0)),
        validity: make_dep_key(0x01),
    };
    let mut current_parent = session.add_seed(init_seed)?;

    // Execute 3 rounds of the bidirectional loop
    for round in 1..=3u64 {
        // Step A: Solver evaluates branch and emits ConstraintHint
        let branch_target: Address = 0x0040_0000 + round * 0x1000;
        let hint_key = make_dep_key(round as u8 * 0x11);
        let hint = ConstraintHint {
            canonical_key: hint_key,
            target: Some(branch_target),
        };
        let hint_id = session.ingest_hint(hint)?;

        // Step B: Fuzzer retrieves solver-derived seed and mutates
        let hint_entry = session.corpus().get(hint_id).unwrap();
        let candidate_bytes = havoc.mutate(&hint_entry.seed.bytes, None);
        let candidate_seed = FuzzSeed {
            bytes: candidate_bytes,
            origin_state: Some(StateId(round)),
            validity: hint_key,
        };

        // Step C: Execution unlocks new CFG edge with +100x boost
        let edge = (branch_target, branch_target + 0x40);
        let delta = CoverageDelta {
            blocks: vec![branch_target + 0x40],
            edges: vec![edge],
        };
        let promo = session.record_coverage_result(current_parent, candidate_seed, delta)?;
        let promo_id = promo.expect("new edge must promote seed");

        let entry = session.corpus().get(promo_id).unwrap();
        assert!(entry.scheduling_weight() >= 200, "entry must have edge boost applied");
        current_parent = promo_id;

        // Step D: New edge branch feeds back into the concolic solver query queue
        let branch_query = make_branch_query(round, round as u8, &[0x01, round as u8])?;
        let waiter = coordinator.submit_query(StateId(round), BranchId(0), hint_key, branch_query);

        // Once 2 queries accumulate, batch triggers automatically (or manual flush for remaining)
        if coordinator.queue_len() >= 2 {
            coordinator.trigger_batch();
            let res = waiter.wait()?;
            assert_eq!(res.outcome, SolverOutcomeKind::Sat);
        }
    }

    // Flush any remaining queries in the queue
    if coordinator.queue_len() > 0 {
        coordinator.flush();
        assert_eq!(coordinator.queue_len(), 0);
    }

    assert!(session.corpus().len() >= 6);
    assert_eq!(session.bridge().hint_count(), 3);
    assert_eq!(session.bridge().coverage_edge_count(), 3);

    Ok(())
}
